package com.gymmind.booking.infrastructure.persistence; import com.gymmind.booking.domain.model.Booking; import com.gymmind.booking.domain.repository.BookingRepository; import org.springframework.stereotype.Repository; import java.util.Optional; @Repository class JpaBookingRepository implements BookingRepository{private final SpringDataBookingRepository d;JpaBookingRepository(SpringDataBookingRepository d){this.d=d;}public Booking save(Booking b){return d.save(b);}public Optional<Booking> findByTenantIdAndMemberIdAndCourseId(Long t,Long m,Long c){return d.findByTenantIdAndMemberIdAndCourseId(t,m,c);}}
